"""Money helpers. Everything downstream works in integer cents."""


def to_cents(amount: float) -> int:
    """Convert a decimal amount such as 19.99 to integer cents."""
    return int(amount * 100)


def percent_of(cents: int, rate: float) -> int:
    """Return rate percent of an amount in cents, rounded half up."""
    return int(cents * rate / 100 + 0.5)


def fmt(cents: int) -> str:
    return f"${cents // 100}.{cents % 100:02d}"

"""An invoice: lines, an optional discount, and tax."""
from dataclasses import dataclass, field

from .money import fmt, percent_of, to_cents


@dataclass
class Line:
    description: str
    unit_price: float
    quantity: int = 1

    def cents(self) -> int:
        return to_cents(self.unit_price) * self.quantity


@dataclass
class Invoice:
    tax_rate: float
    discount_rate: float = 0.0
    lines: list[Line] = field(default_factory=list)

    def add(self, description: str, unit_price: float, quantity: int = 1) -> "Invoice":
        self.lines.append(Line(description, unit_price, quantity))
        return self

    def subtotal(self) -> int:
        return sum(line.cents() for line in self.lines)

    def tax(self) -> int:
        return percent_of(self.subtotal(), self.tax_rate)

    def discount(self) -> int:
        return percent_of(self.subtotal(), self.discount_rate)

    def total(self) -> int:
        return self.subtotal() + self.tax() - self.discount()

    def render(self) -> str:
        rows = [f"{l.description:<20} {l.quantity:>3} x {fmt(to_cents(l.unit_price))}" for l in self.lines]
        rows.append(f"{'total':<20} {fmt(self.total())}")
        return "\n".join(rows)

import unittest

from invoices import Invoice


class InvoiceTest(unittest.TestCase):
    def test_subtotal(self):
        inv = Invoice(tax_rate=8).add("keyboard", 49.50).add("cable", 5.25, 2)
        self.assertEqual(inv.subtotal(), 6000)

    def test_no_discount_total(self):
        inv = Invoice(tax_rate=10).add("monitor", 200.00)
        self.assertEqual(inv.total(), 22000)

    def test_discount_applies_before_tax(self):
        inv = Invoice(tax_rate=10, discount_rate=20).add("desk", 300.00)
        # 30000 - 20% = 24000, plus 10% tax = 26400
        self.assertEqual(inv.total(), 26400)

    def test_line_price_that_floats_badly(self):
        inv = Invoice(tax_rate=0).add("mouse", 19.99, 3)
        self.assertEqual(inv.subtotal(), 5997)

import unittest

from invoices.money import fmt, percent_of, to_cents


class MoneyTest(unittest.TestCase):
    def test_whole_amount(self):
        self.assertEqual(to_cents(12.0), 1200)

    def test_amount_that_floats_badly(self):
        self.assertEqual(to_cents(19.99), 1999)

    def test_percent_rounds_half_up(self):
        self.assertEqual(percent_of(1250, 10), 125)

    def test_format(self):
        self.assertEqual(fmt(1999), "$19.99")

